draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // character
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();

  // action line
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 50 + 20*Math.sin(t), H/2 + 80);
  ctx.stroke();

  // consequence line
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 50 - 20*Math.sin(t), H/2 + 80);
  ctx.stroke();

  // consequence circle
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 50 - 20*Math.sin(t), H/2 + 80, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  ctx.restore();
}
